badExample:
class User {
    String id;
    public boolean equals(Object o) {
        return (o instanceof User) && ((User)o).id.equals(id);
    }
    // Missing hashCode!
}

fixedExample:
class User {
    String id;
    public boolean equals(Object o) {
        return (o instanceof User) && java.util.Objects.equals(id, ((User)o).id);
    }
    public int hashCode() {
        return java.util.Objects.hash(id);
    }
}

