    processOrder();
} catch (Exception e) {
    logger.error("Order processing failed: ", e);
    throw new IllegalStateException("Unable to process order", e);
}

badExample:
class Parent { static void show() { System.out.print("P"); } }
class Child extends Parent { static void show() { System.out.print("C"); } }
Parent ref = new Child();
ref.show(); // Prints 'P', not 'C'!

fixedExample:
class Parent { void show() { System.out.print("P"); } }
class Child extends Parent { @Override void show() { System.out.print("C"); } }
Parent ref = new Child();
ref.show(); // Prints 'C' polymorphically
